#include "webserver/http/response.hpp"
#include "webserver/net/server.hpp"

namespace {

struct WebAppState {
    std::string data_path = "data/";
    SearchMode mode = SearchMode::Or;
    bool compare_mode = false;
    SearchEngine searchengine;
    std::string input;
    std::string near_distance = "5";
    std::vector<Index> search_res;
    AlgoResults compare_metrics{};
    std::size_t selected_result = 0;
    bool has_search = false;
    bool has_compare = false;
    std::string status = "Load a book to start searching.";
};

WebAppState app_state;
std::mutex app_mutex;

std::string html_escape(std::string_view value) {
    std::string escaped;
    escaped.reserve(value.size());

    for (char ch : value) {
        switch (ch) {
            case '&':
                escaped += "&amp;";
                break;
            case '<':
                escaped += "&lt;";
                break;
            case '>':
                escaped += "&gt;";
                break;
            case '"':
                escaped += "&quot;";
                break;
            case '\'':
                escaped += "&#39;";
                break;
            default:
                escaped.push_back(ch);
                break;
        }
    }

    return escaped;
}

std::string attr_escape(std::string_view value) { return html_escape(value); }

std::string mode_to_value(SearchMode mode) {
    switch (mode) {
        case SearchMode::Or:
            return "or";
        case SearchMode::And:
            return "and";
        case SearchMode::Not:
            return "not";
        case SearchMode::Phrase:
            return "phrase";
        case SearchMode::Near:
            return "near";
    }

    return "or";
}

std::string mode_label(std::string_view value) {
    if (value == "or") {
        return "OR";
    }
    if (value == "and") {
        return "AND";
    }
    if (value == "not") {
        return "NOT";
    }
    if (value == "phrase") {
        return "Phrase";
    }
    if (value == "near") {
        return "Near";
    }
    return "Compare";
}

bool parse_mode(std::string_view value, SearchMode& mode, bool& compare_mode) {
    compare_mode = false;
    if (value == "or") {
        mode = SearchMode::Or;
    } else if (value == "and") {
        mode = SearchMode::And;
    } else if (value == "not") {
        mode = SearchMode::Not;
    } else if (value == "phrase") {
        mode = SearchMode::Phrase;
    } else if (value == "near") {
        mode = SearchMode::Near;
    } else if (value == "compare") {
        compare_mode = true;
    } else {
        return false;
    }

    return true;
}

std::string current_mode_value(const WebAppState& state) {
    if (state.compare_mode) {
        return "compare";
    }
    return mode_to_value(state.mode);
}

std::string index_label(const Index& idx) {
    std::ostringstream out;
    out << "Book " << (idx.book_id + 1) << ", Line " << (idx.line + 1) << ", Word "
        << (idx.word_idx + 1);
    return out.str();
}

void append_paragraph(std::ostringstream& out, std::string_view title, std::string_view text) {
    out << "<section class=\"context-block\"><h4>" << title << "</h4>";
    if (text.empty()) {
        out << "<p class=\"muted\">No paragraph.</p>";
    } else {
        out << "<p>" << html_escape(text) << "</p>";
    }
    out << "</section>";
}

void refresh_search(WebAppState& state) {
    state.has_compare = false;
    state.has_search = false;
    state.selected_result = 0;

    if (state.input.empty()) {
        state.search_res.clear();
        state.status = "Enter a query to search.";
        return;
    }

    if (state.compare_mode) {
        state.compare_metrics = tui::make_compare_metrics(state.searchengine.get_loaded_text(), state.input);
        state.search_res.clear();
        state.has_compare = true;
        state.status = "Compared search algorithms for the current query.";
        return;
    }

    SearchRequest request{
        .mode = state.mode,
        .query = state.input,
        .near_distance = tui::parse_near_distance(state.near_distance),
    };
    state.search_res = state.searchengine.search_with_context(request);
    state.has_search = true;
    state.status = "Search complete.";
}

std::vector<std::string> available_files(const WebAppState& state) {
    auto files_res = state.searchengine.list_book_files(state.data_path);
    if (!files_res) {
        return {};
    }

    std::vector<std::string> files;
    for (const std::string& path : files_res.value()) {
        if (!state.searchengine.is_loaded(path)) {
            files.push_back(path);
        }
    }
    return files;
}

std::string render_page(const WebAppState& state) {
    const std::vector<std::string> files = available_files(state);
    const std::vector<std::string> loaded_books = state.searchengine.get_books();
    const std::string mode_value = current_mode_value(state);

    std::ostringstream out;
    out << "<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\">"
        << "<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">"
        << "<title>HarryPotter Search</title>"
        << "<style>"
        << ":root{--bg:#101521;--panel:#171d2b;--panel-2:#20283a;--text:#edf2ff;--muted:#9aa7bd;--line:#303a52;--accent:#f5c2e7;--accent-2:#89b4fa;--green:#a6e3a1;--red:#f38ba8;}"
        << "*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at top left,#23304d 0,#101521 34rem);color:var(--text);font-family:ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;line-height:1.5;}"
        << "a{color:inherit}.shell{width:min(1280px,calc(100% - 32px));margin:0 auto;padding:32px 0 48px}.hero{display:flex;justify-content:space-between;gap:24px;align-items:flex-end;margin-bottom:24px}.eyebrow{color:var(--accent);font-weight:700;letter-spacing:.12em;text-transform:uppercase;font-size:12px}h1{font-size:clamp(34px,5vw,58px);line-height:1;margin:8px 0}.hero p{color:var(--muted);max-width:720px}.grid{display:grid;grid-template-columns:360px minmax(0,1fr);gap:20px}.card{background:linear-gradient(180deg,rgba(255,255,255,.05),rgba(255,255,255,.02));border:1px solid var(--line);border-radius:22px;padding:20px;box-shadow:0 20px 70px rgba(0,0,0,.28)}.card h2{margin:0 0 14px;font-size:20px}.stack{display:grid;gap:14px}.field{display:grid;gap:7px}label{font-size:13px;color:var(--muted);font-weight:700}select,input{width:100%;border:1px solid var(--line);background:var(--panel-2);color:var(--text);border-radius:14px;padding:12px 13px;font:inherit}button,.button{border:0;border-radius:14px;background:linear-gradient(135deg,var(--accent),var(--accent-2));color:#101521;font-weight:800;padding:12px 14px;cursor:pointer;text-decoration:none;display:inline-flex;justify-content:center}.secondary{background:var(--panel-2);color:var(--text);border:1px solid var(--line)}.muted{color:var(--muted)}.status{border-left:4px solid var(--accent);padding:10px 12px;background:rgba(245,194,231,.08);border-radius:12px}.chips{display:flex;flex-wrap:wrap;gap:8px}.chip{padding:7px 10px;border-radius:999px;background:rgba(137,180,250,.13);border:1px solid rgba(137,180,250,.3);font-size:13px}.layout{display:grid;grid-template-columns:minmax(0,1fr) 420px;gap:20px}.results{display:grid;gap:10px;max-height:680px;overflow:auto;padding-right:4px}.result{display:block;text-decoration:none;border:1px solid var(--line);border-radius:16px;padding:12px;background:rgba(255,255,255,.03)}.result:hover,.result.active{border-color:var(--accent);background:rgba(245,194,231,.1)}.result strong{display:block;margin-bottom:4px}.context-block{border-top:1px solid var(--line);padding-top:14px;margin-top:14px}.context-block:first-child{border-top:0;margin-top:0;padding-top:0}.context-block p{white-space:pre-wrap}.metrics{width:100%;border-collapse:collapse}.metrics th,.metrics td{text-align:left;padding:10px;border-bottom:1px solid var(--line)}.metrics th{color:var(--green)}.bar{height:10px;border-radius:99px;background:#2b344a;overflow:hidden}.bar span{display:block;height:100%;background:linear-gradient(90deg,var(--accent-2),var(--accent))}@media(max-width:980px){.grid,.layout{grid-template-columns:1fr}.hero{display:block}}"
        << "</style></head><body><main class=\"shell\">";

    out << "<section class=\"hero\"><div><div class=\"eyebrow\">HarryPotter Web</div>"
        << "<h1>Search the books</h1><p>Web version of the TUI workflow: load books, choose search mode, inspect context, and compare algorithms.</p></div>"
        << "<div class=\"card\"><strong>" << loaded_books.size() << "</strong><span class=\"muted\"> loaded books</span><br>"
        << "<strong>" << state.search_res.size() << "</strong><span class=\"muted\"> results</span></div></section>";

    out << "<div class=\"grid\"><aside class=\"stack\">";
    out << "<section class=\"card stack\"><h2>Load Books</h2>";
    out << "<form class=\"stack\" method=\"post\" action=\"/books/load\"><div class=\"field\"><label for=\"book\">Available book</label><select id=\"book\" name=\"book\">";
    if (files.empty()) {
        out << "<option value=\"\">No unloaded txt files</option>";
    } else {
        for (const std::string& file : files) {
            out << "<option value=\"" << attr_escape(file) << "\">" << html_escape(tui::get_filename(file)) << "</option>";
        }
    }
    out << "</select></div><button type=\"submit\">Load selected book</button></form>";
    out << "<div><label>Loaded</label><div class=\"chips\">";
    if (loaded_books.empty()) {
        out << "<span class=\"muted\">None yet.</span>";
    } else {
        for (const std::string& book : loaded_books) {
            out << "<span class=\"chip\">" << html_escape(book) << "</span>";
        }
    }
    out << "</div></div></section>";

    out << "<section class=\"card stack\"><h2>Search Controls</h2>"
        << "<form class=\"stack\" method=\"post\" action=\"/search\">"
        << "<div class=\"field\"><label for=\"mode\">Mode</label><select id=\"mode\" name=\"mode\">";
    for (std::string_view mode : std::array<std::string_view, 6>{"or", "and", "not", "phrase", "near", "compare"}) {
        out << "<option value=\"" << mode << "\"";
        if (mode == mode_value) {
            out << " selected";
        }
        out << ">" << mode_label(mode) << "</option>";
    }
    out << "</select></div>"
        << "<div class=\"field\"><label for=\"query\">Query</label><input id=\"query\" name=\"query\" value=\"" << attr_escape(state.input) << "\" placeholder=\"harry potter\"></div>"
        << "<div class=\"field\"><label for=\"near\">Near distance</label><input id=\"near\" name=\"near_distance\" value=\"" << attr_escape(state.near_distance) << "\"></div>"
        << "<button type=\"submit\">Run</button></form><div class=\"status\">" << html_escape(state.status) << "</div></section>";
    out << "</aside><section class=\"layout\">";

    out << "<section class=\"card\"><h2>Results</h2>";
    if (state.compare_mode && state.has_compare) {
        const auto fastest = std::ranges::min_element(state.compare_metrics, {}, &AlgoResult::use_time_ms);
        const auto fewest = std::ranges::min_element(state.compare_metrics, {}, &AlgoResult::compare_count);
        const auto max_compare = std::ranges::max_element(state.compare_metrics, {}, &AlgoResult::compare_count)->compare_count;
        out << "<p class=\"muted\">Fastest: <strong>" << html_escape(fastest->name) << "</strong> (" << fastest->use_time_ms
            << " ms). Fewest comparisons: <strong>" << html_escape(fewest->name) << "</strong> (" << fewest->compare_count << ").</p>";
        out << "<table class=\"metrics\"><thead><tr><th>Algorithm</th><th>Matches</th><th>Comparisons</th><th>Time(ms)</th></tr></thead><tbody>";
        for (const AlgoResult& metric : state.compare_metrics) {
            out << "<tr><td>" << html_escape(metric.name) << "</td><td>" << metric.match_count << "</td><td>" << metric.compare_count
                << "<div class=\"bar\"><span style=\"width:" << (max_compare == 0 ? 0 : (metric.compare_count * 100 / max_compare))
                << "%\"></span></div></td><td>" << metric.use_time_ms << "</td></tr>";
        }
        out << "</tbody></table>";
    } else if (state.search_res.empty()) {
        out << "<p class=\"muted\">No search results to show.</p>";
    } else {
        out << "<div class=\"results\">";
        for (std::size_t i = 0; i < state.search_res.size(); ++i) {
            out << "<a class=\"result" << (i == state.selected_result ? " active" : "") << "\" href=\"/detail?idx=" << i << "\">"
                << "<strong>" << html_escape(index_label(state.search_res[i])) << "</strong>"
                << "<span class=\"muted\">Open surrounding paragraphs</span></a>";
        }
        out << "</div>";
    }
    out << "</section>";

    out << "<section class=\"card\"><h2>Detail</h2>";
    if (!state.compare_mode && !state.search_res.empty() && state.selected_result < state.search_res.size()) {
        const SearchResult context = state.searchengine.get_context(state.search_res[state.selected_result]);
        append_paragraph(out, "Previous Paragraph", std::get<0>(context));
        append_paragraph(out, "Current Paragraph", std::get<1>(context));
        append_paragraph(out, "Next Paragraph", std::get<2>(context));
    } else {
        out << "<p class=\"muted\">Select a result to view context.</p>";
    }
    out << "</section></section></div></main></body></html>";

    return out.str();
}

Result<void> render(Connection& conn) {
    std::lock_guard<std::mutex> lock(app_mutex);
    return write_html(conn, HttpStatus::OK, render_page(app_state));
}

Result<void> handle_load(Connection& conn, const QueryFields& fields) {
    std::lock_guard<std::mutex> lock(app_mutex);

    const auto book = fields.find("book");
    if (book == fields.end() || book->second.empty()) {
        app_state.status = "Choose a book before loading.";
        return write_html(conn, HttpStatus::OK, render_page(app_state));
    }

    auto load_res = app_state.searchengine.load_file(book->second);
    if (!load_res) {
        app_state.status = "Failed to load " + tui::get_filename(book->second) + ".";
    } else if (load_res.value() == 0) {
        app_state.status = tui::get_filename(book->second) + " is already loaded.";
    } else {
        app_state.status = "Loaded " + tui::get_filename(book->second) + ".";
    }

    if (!app_state.input.empty()) {
        refresh_search(app_state);
    }

    return write_html(conn, HttpStatus::OK, render_page(app_state));
}

Result<void> handle_search(Connection& conn, const QueryFields& fields) {
    std::lock_guard<std::mutex> lock(app_mutex);

    if (const auto query = fields.find("query"); query != fields.end()) {
        app_state.input = query->second;
    }
    if (const auto near = fields.find("near_distance"); near != fields.end()) {
        app_state.near_distance = near->second;
    }
    if (const auto mode = fields.find("mode"); mode != fields.end()) {
        if (!parse_mode(mode->second, app_state.mode, app_state.compare_mode)) {
            app_state.status = "Unknown search mode.";
            return write_html(conn, HttpStatus::OK, render_page(app_state));
        }
    }

    refresh_search(app_state);
    return write_html(conn, HttpStatus::OK, render_page(app_state));
}

Result<void> handle_detail(Connection& conn, const QueryFields& fields) {
