    std::lock_guard<std::mutex> lock(app_mutex);

    const auto book = fields.find("book");
    if (book == fields.end() || book->second.empty()) {
        app_state.status = "Choose a book before loading.";
        return write_html(conn, HttpStatus::OK, render_page(app_state));
    }

    auto load_res = app_state.searchengine.load_file(book->second);
    if (!load_res) {
        app_state.status = "Failed to load " + tui::get_filename(book->second) + ".";
    } else if (load_res.value() == 0) {
        app_state.status = tui::get_filename(book->second) + " is already loaded.";
    } else {
        app_state.status = "Loaded " + tui::get_filename(book->second) + ".";
    }

    if (!app_state.input.empty()) {
        refresh_search(app_state);
    }

    return write_html(conn, HttpStatus::OK, render_page(app_state));
}

Result<void> handle_search(Connection& conn, const QueryFields& fields) {
    std::lock_guard<std::mutex> lock(app_mutex);

    if (const auto query = fields.find("query"); query != fields.end()) {
        app_state.input = query->second;
    }
    if (const auto near = fields.find("near_distance"); near != fields.end()) {
        app_state.near_distance = near->second;
    }
    if (const auto mode = fields.find("mode"); mode != fields.end()) {
        if (!parse_mode(mode->second, app_state.mode, app_state.compare_mode)) {
            app_state.status = "Unknown search mode.";
            return write_html(conn, HttpStatus::OK, render_page(app_state));
        }
    }

    refresh_search(app_state);
    return write_html(conn, HttpStatus::OK, render_page(app_state));
}

