    std::lock_guard<std::mutex> lock(app_mutex);

    if (const auto idx = fields.find("idx"); idx != fields.end()) {
        std::size_t pos = 0;
        try {
            pos = static_cast<std::size_t>(std::stoull(idx->second));
        } catch (const std::exception&) {
            pos = 0;
        }
        if (pos < app_state.search_res.size()) {
            app_state.selected_result = pos;
            app_state.compare_mode = false;
            app_state.status = "Showing result context.";
        }
    }

    return write_html(conn, HttpStatus::OK, render_page(app_state));
}

